const DRY = $('Webhook').first().json.body && $('Webhook').first().json.body.dry === true;
const R = $json.valueRanges || [];
const pick = (n) => (R.find(x => String(x.range||'').indexOf(n) === 0) || {}).values || [];
const crit = pick('INVESTOR_CRITERIA');
const inv  = pick('INVESTORS!');
const g = (row,i) => (row && row[i] != null) ? String(row[i]).trim() : '';
if (!crit.length || !inv.length) throw new Error('a tab came back empty');
const critH = (crit[0]||[]).map(h => String(h||'').trim());
const invH  = (inv[0]||[]).map(h => String(h||'').trim());
if (critH[0] !== 'sheet_row' || critH[1] !== 'investor') throw new Error('INVESTOR_CRITERIA header unexpected: ' + critH.slice(0,3).join('|'));
if (invH[0] !== 'investor') throw new Error('INVESTORS header unexpected: ' + invH.slice(0,3).join('|'));
const KEY = 'first bridge';
for (let i=1;i<inv.length;i++){ if (g(inv[i],0).toLowerCase().indexOf(KEY) >= 0) throw new Error('INVESTORS already holds a First Bridge row at ' + (i+1)); }
for (let i=1;i<crit.length;i++){ if (g(crit[i],1).toLowerCase().indexOf(KEY) >= 0) throw new Error('INVESTOR_CRITERIA already holds a First Bridge row at ' + (i+1)); }
const last = (rows) => { let L=0; for (let i=1;i<rows.length;i++){ const r=rows[i]; if (r && r.some(c => String(c||'').trim() !== '')) L=i; } return L; };
const invNew  = last(inv) + 2;
const critNew = last(crit) + 2;
if (inv[invNew-1] && inv[invNew-1].some(c => String(c||'').trim() !== '')) throw new Error('INVESTORS target row ' + invNew + ' is not empty');
if (crit[critNew-1] && crit[critNew-1].some(c => String(c||'').trim() !== '')) throw new Error('INVESTOR_CRITERIA target row ' + critNew + ' is not empty');
const colL = (i) => { let s=''; i++; while (i>0){ const m=(i-1)%26; s=String.fromCharCode(65+m)+s; i=Math.floor((i-1)/26); } return s; };
const THESIS = 'Thesis in Priyank Jain own words to Shradhaa on LinkedIn, 29 Sep 2026: "we are sector agnostic ... looking to invest USD 8-10 million, growth stage companies". First Bridge is a SEBI Category II Alternative Investment Fund, a growth focused private equity fund for the Indian market. The firm describes itself as providing inflection capital to high growth companies and preferring to back first generation entrepreneurs. Ten portfolio companies are listed, among them Leap, Mahaveer Finance, Lavie, Innefu, Zuppa, Tea Post, Berar Finance and Hyuga Life. Institutional backers named on the site include SIDBI, LIC, PNB, NABARD and GIC Re.';
const RULES = 'Created 6 Oct 2026 by the onboarding engine from the thesis captured on LI_OUTREACH row 10, which had never reached either database tab. HIS OWN WORDS: sector agnostic, growth stage, USD 8 to 10 million. OUR MAPPING, not his words: cheque_min_cr 68 and cheque_max_cr 85 from USD 8 to 10 million at INR 85 per US dollar; stage_min SERIES_B and stage_max SERIES_C_PLUS mapped from growth stage, he named no series; revenue_required Y mapped from growth stage, he did not state it. sector_mode AGNOSTIC is taken straight from his words. DISCREPANCY TO WATCH: he says sector agnostic, but firstbridgefund.com states four focus sectors, consumer facing businesses, financial services, niche manufacturing and business services. Until he confirms, treat the website list as the likelier real filter and check sector by eye. The cheque ceiling is filled here because he stated an upper bound himself; almost every other row leaves it blank and so fails open.';
const UNCHK = 'Website names four focus sectors against his own sector agnostic claim. Growth stage is not defined by series. On the book as at 6 Oct 2026 only one round reaches his cheque band, so very few matches are expected by design, and that is correct rather than a fault.';
const EVID = 'LinkedIn reply to Shradhaa 29 Sep 2026 17:51, recorded on LI_OUTREACH row 10. Email given by him, priyank.jain@firstbridgefund.com. firstbridgefund.com fetched and verified live on 6 Oct 2026: substantive site with portfolio, strategy and named institutional backers, not a parked lander.';
const SRC = 'LI_OUTREACH row 10; firstbridgefund.com; investor stated 29 Sep 2026';
const invVals = { investor: 'First Bridge Private Equity Fund', contact_person: 'Priyank Jain', email: 'priyank.jain@firstbridgefund.com', sector: 'Sector agnostic as stated by him; site lists consumer facing, financial services, niche manufacturing, business services', stage: 'Growth', cheque_inr_cr: 'US$8 to 10 million (INR 68 to 85 Cr)', last_contacted_any: '2026-09-29', contacted_by: 'Shradhaa' };
const critVals = { sheet_row: String(invNew), investor: 'First Bridge Private Equity Fund', investor_type: 'Private equity fund (SEBI Category II AIF)', status: 'ACTIVE', confirmed: 'USER', sector_mode: 'AGNOSTIC', models_in: 'ANY', stage_min: 'SERIES_B', stage_max: 'SERIES_C_PLUS', cheque_min_cr: '68', cheque_max_cr: '85', arr_min_strict: 'N', revenue_required: 'Y', women_only: 'N', excludes_jain_sensitive: 'N', geography_scope: 'INDIA', unchecked_requirements: UNCHK, thesis_summary: THESIS, evidence: EVID, confidence: 'HIGH', rule_notes: RULES, sources: SRC };
const BAD = /[–—]|&mdash;|&ndash;/;
const data = []; const skipped = []; const wrote = [];
const push = (tab, header, vals, rowNo) => { for (const k of Object.keys(vals)) { const ci = header.indexOf(k); if (ci < 0) { skipped.push(tab + '.' + k); continue; } const val = vals[k]; if (BAD.test(val)) throw new Error('dash character in ' + tab + '.' + k); data.push({ range: tab + '!' + colL(ci) + rowNo, values: [[val]] }); wrote.push(tab + '.' + k + '=' + colL(ci) + rowNo); } };
push('INVESTORS', invH, invVals, invNew);
push('INVESTOR_CRITERIA', critH, critVals, critNew);
if (skipped.length) throw new Error('header has no column for: ' + skipped.join(', '));
return [{ json: { dry: DRY, body: { valueInputOption: 'RAW', data: data }, investors_row: invNew, criteria_row: critNew, cells: data.length, wrote: wrote, crit_header_len: critH.length, inv_header_len: invH.length } }];
